"""Standalone state-adaptive Kaggriculture agent."""

from __future__ import annotations

import base64
import copy
import io
import json
import math
import zlib
from collections import Counter
from dataclasses import dataclass
from typing import Any

import numpy as np

CROPS = ("WHEAT", "CARROT", "TOMATO", "STRAWBERRY", "MELON")
ANIMALS = ("GOOSE", "COW", "SHEEP")
ITEMS = (*CROPS, "EGG", "MILK", "WOOL", "FERTILIZER", *ANIMALS)

PRODUCTS = (*CROPS, "EGG", "MILK", "WOOL", "FERTILIZER")
SHED_ITEMS = (*PRODUCTS, *ANIMALS)
SHOPS = ("BAKERY", "BRUNCH_SPOT", "FARMERS_MARKET", "ICE_CREAM_SHOP", "PET_CAFE", "PIZZA_SHOP", "SMOOTHIE_SHOP", "YARN_STORE")
BOARD_SIZE = 10
SPATIAL_CHANNELS = 20
GLOBAL_FEATURES = 68
MAX_HANDS = 12
_BASE_ACTION_ID = 293538238

@dataclass(frozen=True, slots=True)
class TapeSelectorConfig:
    branch_step: int = 145
    neighbors: int = 3
    distance_epsilon: float = 1e-6
    ood_threshold: float = float("inf")
    risk_coefficient: float = 0.0

@dataclass(frozen=True, slots=True)
class TapeSelectorCheckpoint:
    config: TapeSelectorConfig
    feature_mean: np.ndarray
    feature_scale: np.ndarray
    train_features: np.ndarray
    q_values: np.ndarray
    global_action: int
    action_ids: tuple[int, ...]
    metadata: dict[str, Any]

def _tile_features(farm: dict[str, Any]) -> list[float]:
    kinds: Counter[str] = Counter()
    crops: Counter[str] = Counter()
    animals: Counter[str] = Counter()
    ready = 0
    needs_water = 0
    fertilizer = 0
    for row in farm.get("tiles", []):
        for tile in row:
            if not isinstance(tile, dict):
                continue
            kind = str(tile.get("kind", "EMPTY"))
            kinds[kind] += 1
            crop = tile.get("crop")
            if crop is not None:
                crops[str(crop)] += 1
            animal = tile.get("animal")
            if animal is not None:
                animals[str(animal)] += 1
            ready += int(float(tile.get("yield_units", 0) or 0) > 0)
            needs_water += int(kind == "PLANT" and not tile.get("watered_today", False))
            fertilizer += int(float(tile.get("fertilizer_available", 0) or 0) > 0)

    return [
        len(farm.get("hands", [])) / 16.0,
        len(farm.get("unlocked_quadrants", [])) / 4.0,
        float(farm.get("hires_today", 0) or 0) / 16.0,
        kinds["WEED"] / 100.0,
        kinds["PASTURE"] / 30.0,
        kinds["COOP"] / 30.0,
        ready / 30.0,
        needs_water / 30.0,
        fertilizer / 30.0,
        *(crops[crop] / 30.0 for crop in CROPS),
        *(animals[animal] / 30.0 for animal in ANIMALS),
    ]

def encode_selector_features(observation: dict[str, Any]) -> np.ndarray:
    """Encode only information available to the candidate at decision time."""
    player = int(observation.get("player", 0))
    opponent = 1 - player
    farms = observation["farms"]
    candidate_farm = farms[player]
    opponent_farm = farms[opponent]
    candidate_money = float(candidate_farm.get("money", 0) or 0)
    opponent_money = float(opponent_farm.get("money", 0) or 0)
    prices = observation.get("market", {}).get("prices", {})
    private = observation.get("private", {})
    shed = private.get("shed", {})
    seeds = private.get("seeds", {})
    inventory: Counter[str] = Counter()
    for unit_inventory in private.get("inventories", []):
        inventory.update(
            {
                str(item): int(quantity)
                for item, quantity in unit_inventory.items()
            }
        )

    features = [
        float(observation.get("step", 0) or 0) / 719.0,
        float(observation.get("day", 0) or 0) / 30.0,
        float(observation.get("hour", 0) or 0) / 24.0,
        candidate_money / 200_000.0,
        opponent_money / 200_000.0,
        (candidate_money - opponent_money) / 200_000.0,
        *(float(prices.get(item, 0) or 0) / 2_000.0 for item in ITEMS),
        *_tile_features(candidate_farm),
        *_tile_features(opponent_farm),
        *(float(shed.get(item, 0) or 0) / 200.0 for item in ITEMS),
        *(float(seeds.get(crop, 0) or 0) / 50.0 for crop in CROPS),
        *(float(inventory[item]) / 100.0 for item in ITEMS),
    ]
    return np.asarray(features, dtype=np.float64)

def _scaled(value: Any, scale: float) -> float:
    numeric = max(float(value or 0.0), 0.0)
    return float(np.clip(math.log1p(numeric) / math.log1p(scale), 0.0, 2.0))

def encode_spatial_observation(observation: dict[str, Any]) -> tuple[np.ndarray, np.ndarray]:
    """Encode one observation without leaking the opponent's private state."""
    player = int(observation["player"])
    day = int(observation.get("day", 0))
    farms = observation["farms"]
    perspective = (player, 1 - player)
    spatial = np.zeros((2, BOARD_SIZE, BOARD_SIZE, SPATIAL_CHANNELS), dtype=np.float32)

    crop_channels = {crop: 2 + index for index, crop in enumerate(CROPS)}
    animal_channels = {animal: 9 + index for index, animal in enumerate(ANIMALS)}
    for board_index, farm_index in enumerate(perspective):
        farm = farms[farm_index]
        tiles = farm["tiles"]
        if len(tiles) != BOARD_SIZE or any(len(row) != BOARD_SIZE for row in tiles):
            raise ValueError("spatial encoder requires a 10x10 board")
        board = spatial[board_index]
        for y, row in enumerate(tiles):
            for x, tile in enumerate(row):
                if tile == "LOCKED":
                    continue
                board[y, x, 0] = 1.0
                if not isinstance(tile, dict):
                    continue
                kind = str(tile.get("kind", ""))
                if kind == "WEED":
                    board[y, x, 1] = 1.0
                crop = tile.get("crop")
                if crop in crop_channels:
                    board[y, x, crop_channels[crop]] = 1.0
                if kind == "COOP":
                    board[y, x, 7] = 1.0
                elif kind == "PASTURE":
                    board[y, x, 8] = 1.0
                animal = tile.get("animal")
                if animal in animal_channels:
                    board[y, x, animal_channels[animal]] = 1.0
                board[y, x, 12] = float(tile.get("watered_today") is True)
                board[y, x, 13] = _scaled(tile.get("yield_units", 0), 16.0)
                board[y, x, 14] = float(int(tile.get("fertilized_until_day", -1)) >= day)
                board[y, x, 15] = float(tile.get("fed_today") is True)
                board[y, x, 16] = float(tile.get("cared_today") is True)
                board[y, x, 17] = float(tile.get("fertilizer_available") is True)

        farmer_x, farmer_y = farm["farmer"]
        board[int(farmer_y), int(farmer_x), 18] = 1.0
        for hand_x, hand_y in farm.get("hands", []):
            board[int(hand_y), int(hand_x), 19] += 1.0

    step = int(observation.get("step", day * 24 + int(observation.get("hour", 0))))
    hour = int(observation.get("hour", step % 24))
    angle = 2.0 * math.pi * hour / 24.0
    global_values = [
        step / 719.0,
        day / 30.0,
        hour / 23.0,
        math.sin(angle),
        math.cos(angle),
    ]
    for farm_index in perspective:
        farm = farms[farm_index]
        global_values.extend(
            (
                _scaled(farm.get("money", 0), 200_000.0),
                len(farm.get("hands", [])) / MAX_HANDS,
                int(farm.get("hires_today", 0)) / MAX_HANDS,
                len(farm.get("unlocked_quadrants", [])) / 4.0,
            )
        )

    private = observation["private"]
    shed = private.get("shed", {})
    seeds = private.get("seeds", {})
    inventories = private.get("inventories", [])
    carried = {
        item: sum(int(inventory.get(item, 0)) for inventory in inventories)
        for item in SHED_ITEMS
    }
    global_values.extend(_scaled(shed.get(item, 0), 100.0) for item in SHED_ITEMS)
    global_values.extend(_scaled(seeds.get(crop, 0), 100.0) for crop in CROPS)
    global_values.extend(_scaled(carried[item], 100.0) for item in SHED_ITEMS)

    market = observation["market"]
    market_inventory = market.get("inventory", {})
    prices = market.get("prices", {})
    global_values.extend(_scaled(market_inventory.get(item, 0), 20_000.0) for item in PRODUCTS)
    global_values.extend(_scaled(prices.get(item, 0), 10_000.0) for item in PRODUCTS)
    unlocked_shops = set(observation.get("town", {}).get("unlocked_shops", []))
    global_values.extend(float(shop in unlocked_shops) for shop in SHOPS)

    global_features = np.asarray(global_values, dtype=np.float32)
    if global_features.shape != (GLOBAL_FEATURES,):
        raise AssertionError(
            f"expected {GLOBAL_FEATURES} global features, got {global_features.shape}"
        )
    return spatial, global_features

def _encode_spatial_selector_features(observation: dict[str, object]) -> np.ndarray:
    spatial, global_features = encode_spatial_observation(observation)
    return np.concatenate((spatial.reshape(-1), global_features))

def _encode_features(observation):
    return _encode_spatial_selector_features(observation)

def predict_q(
    checkpoint: TapeSelectorCheckpoint, features: np.ndarray
) -> tuple[np.ndarray, float]:
    normalized = (features - checkpoint.feature_mean) / checkpoint.feature_scale
    distances = np.linalg.norm(checkpoint.train_features - normalized, axis=1)
    count = min(checkpoint.config.neighbors, len(distances))
    nearest = np.argpartition(distances, count - 1)[:count]
    minimum_distance = float(distances[nearest].min())
    if minimum_distance > checkpoint.config.ood_threshold:
        values = np.full(checkpoint.q_values.shape[1], -np.inf)
        values[checkpoint.global_action] = 0.0
        return values, minimum_distance
    weights = 1.0 / (distances[nearest] + checkpoint.config.distance_epsilon)
    neighbor_values = checkpoint.q_values[nearest]
    mean_values = np.average(neighbor_values, axis=0, weights=weights)
    centered = neighbor_values - mean_values
    variance = np.average(np.square(centered), axis=0, weights=weights)
    values = mean_values - checkpoint.config.risk_coefficient * np.sqrt(variance)
    return values, minimum_distance

def select_action(
    checkpoint: TapeSelectorCheckpoint, features: np.ndarray
) -> tuple[int, np.ndarray, float]:
    values, distance = predict_q(checkpoint, features)
    column = int(np.argmax(values))
    return checkpoint.action_ids[column], values, distance

